func GeneratedManifestFieldDispositions() map[string]string {
	result := make(map[string]string, len(generatedManifestFieldDispositions))
	for pointer, disposition := range generatedManifestFieldDispositions {
		result[pointer] = disposition
	}
	return result
}

func buildGeneratedManifest(name string, raw map[string]any) (FrozenManifest, error) {
	switch name {
	case "failure-injection":
		{
			value, err := buildFailureInjectionManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "http-rate-limits":
		{
			value, err := buildHTTPRateLimitsManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "migration-policy":
		{
			value, err := buildMigrationPolicyManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "nats-permissions":
		{
			value, err := buildNATSPermissionsManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "phase0-file-manifest":
		{
			value, err := buildPhase0FileManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "recovery-policy":
		{
			value, err := buildRecoveryPolicyManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "security-values":
		{
			value, err := buildSecurityValuesManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "state-machines":
		{
			value, err := buildStateMachinesManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "transaction-boundaries":
		{
			value, err := buildTransactionBoundariesManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	case "websocket-protocol":
		{
			value, err := buildWebSocketProtocolManifest(raw)
			if err != nil {
				return nil, err
			}
			return value, nil
		}
	default:
		return nil, fmt.Errorf("platformcontract: no generated manifest type for %q", name)
	}
}
